def describe_change(change_cm):
    if change_cm > 0:
        return "forward"
    if change_cm < 0:
        return "backward"
    return "stationary"

print(describe_change(3), describe_change(-3), describe_change(0))

def mean_change_cm(changes):
    if len(changes) == 0:
        raise ValueError("cannot average an empty list")
    return sum(changes) / len(changes)

assert mean_change_cm([3, 2, 2]) == 7 / 3
assert describe_change(3) == "forward"
assert describe_change(-3) == "backward"
assert describe_change(0) == "stationary"

