assert cm_to_m(150) == 1.5

def finite_array(x, dtype=np.float64):
    value = np.asarray(x, dtype=dtype)
    if not np.all(np.isfinite(value)):
        bad = np.argwhere(~np.isfinite(value))[:3].tolist()
        raise FloatingPointError(f"non-finite values at {bad}")
    return value

values = finite_array([1e-8, 0.0, -2.0])
assert values.dtype == np.float64
try:
    finite_array([np.nan])
except FloatingPointError:
    pass
else:
    raise AssertionError("NaN must be rejected")

def logsumexp(values):
    values = finite_array(values)
    pivot = np.max(values)
    return float(pivot + np.log(np.sum(np.exp(values - pivot))))

score = logsumexp([1000.0, 1001.0])
assert np.isfinite(score)

