"""Small, dependency-light scientific-programming contracts."""

from __future__ import annotations

from dataclasses import asdict, dataclass

import numpy as np


class ScientificPythonContractError(ValueError):
    """Raised when a scientific-computing interface is ambiguous or unsafe."""


def finite_array(x, dtype=np.float64):
    value = np.asarray(x, dtype=dtype)
    if not np.all(np.isfinite(value)):
        bad = np.argwhere(~np.isfinite(value))[:3].tolist()
        raise FloatingPointError(f"non-finite values at {bad}")
    return value


def logsumexp(values):
    values = finite_array(values).reshape(-1)
    if values.size == 0:
        raise ValueError("empty input")
    pivot = np.max(values)
    return float(pivot + np.log(np.sum(np.exp(values - pivot))))


def nearest_distance(query, candidates, block=1024):
    query = finite_array(query).reshape(1, -1)
    candidates = finite_array(candidates)
    if candidates.ndim != 2 or candidates.shape[1] != query.shape[1]:
        raise ScientificPythonContractError("candidate shape mismatch")
    if candidates.shape[0] == 0:
        raise ScientificPythonContractError("candidates must be non-empty")
    if not isinstance(block, (int, np.integer)) or block <= 0:
        raise ScientificPythonContractError("block must be a positive integer")
    best = np.inf
    for start in range(0, len(candidates), block):
        chunk = candidates[start:start + block]
        best = min(best, float(np.linalg.norm(chunk - query, axis=1).min()))
    return best


def make_record(episode, index, time_s, frame, observation, action, status):
    time_s = float(time_s)
    if not episode or not isinstance(index, (int, np.integer)) or index < 0:
        raise ScientificPythonContractError("invalid episode identity or index")
    if not np.isfinite(time_s) or time_s < 0:
        raise ScientificPythonContractError("time_s must be finite and non-negative")
    if frame not in {"base", "tool", "camera"}:
        raise ScientificPythonContractError("unknown frame")
    return {
        "schema_version": 1,
        "episode": str(episode), "index": int(index), "time_s": float(time_s),
        "frame": frame, "observation": finite_array(observation).tolist(),
        "action": finite_array(action).tolist(), "status": str(status),
    }


def summarize(values):
    values = finite_array(values).reshape(-1)
    if values.size == 0:
        raise ValueError("empty metric")
    return {
        "n": int(values.size),
        "mean": float(values.mean()),
        "median": float(np.median(values)),
        "q10": float(np.quantile(values, 0.10)),
        "q90": float(np.quantile(values, 0.90)),
    }


@dataclass(frozen=True)
class Config:
    seed: int = 7
    device: str = "cpu"
    control_hz: float = 20.0
    output_dir: str = "artifacts/run"

    def __post_init__(self):
        if not isinstance(self.seed, (int, np.integer)):
            raise ScientificPythonContractError("seed must be an integer")
        if not self.device or not isinstance(self.device, str):
            raise ScientificPythonContractError("device must be a non-empty string")
        if not np.isfinite(self.control_hz) or self.control_hz <= 0:
            raise ScientificPythonContractError("control_hz must be positive and finite")
        if not self.output_dir or not isinstance(self.output_dir, str):
            raise ScientificPythonContractError("output_dir must be a non-empty string")


def override(config, **kwargs):
    if not isinstance(config, Config):
        raise ScientificPythonContractError("config must be a Config instance")
    data = asdict(config)
    unknown = set(kwargs) - set(data)
    if unknown:
        raise KeyError(f"unknown config keys: {sorted(unknown)}")
    data.update(kwargs)
    return Config(**data)


def demo():
    return {
        "stable_logsumexp": logsumexp([1000.0, 1001.0]),
        "nearest": nearest_distance([0., 0.], [[1., 0.], [0., 0.1]]),
        "summary": summarize([0.2, 0.4, 0.8]),
        "config": asdict(override(Config(), control_hz=25.0)),
    }


if __name__ == "__main__":
    print(demo())
